export const dictionaries: Record<Language, Record<string, string>> = Object.fromEntries(
  languages.map(({ code }, column) => [code, Object.fromEntries(
    Object.entries(catalog).map(([key, values]) => [key, values[column]]),
  )]),
) as Record<Language, Record<string, string>>;

/** Preserve unresolved keys/placeholders so unexpected diagnostics remain inspectable. */
export function t(language: Language, key: string, vars?: Record<string, string | number>): string {
  const dictionary = Object.hasOwn(dictionaries, language) ? dictionaries[language] : dictionaries.en;
  const template = Object.hasOwn(dictionary, key) ? dictionary[key] : key;
  return template.replace(/\{([A-Za-z][A-Za-z0-9_]*)\}/g, (placeholder, name: string) =>
    vars && Object.hasOwn(vars, name) ? String(vars[name]) : placeholder,
  );
}
